import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'preact/hooks';
import type { FunctionComponent } from 'preact';
import { materialById, materials, recipesForMaterial, type Material } from './data';

const VERSION = '1.3.24';
const COMMIT_HASH = 'dev';
const STORAGE_KEY = 'factorio-bus-planner';
const FLOW_DIRECTION_STORAGE_KEY = 'factorio-bus-flow-direction';
const MAX_HISTORY = 60;

interface Lane {
  id: string;
  material: string;
}

interface Station {
  id: string;
  material: string;
  side: 'left' | 'right';
  busInputs?: string[];
}

interface Plan {
  lanes: Lane[];
  stations: Station[];
}

type DragPayload = { kind: 'material' | 'lane' | 'station'; id: string };
type FlowDirection = 'up' | 'down';

const emptyPlan: Plan = { lanes: [], stations: [] };

function newId(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

function loadPlan(): Plan {
  const encoded = new URLSearchParams(window.location.hash.slice(1)).get('plan');
  const stored = encoded ? decodePlan(encoded) : localStorage.getItem(STORAGE_KEY);
  if (!stored) return emptyPlan;
  try {
    const parsed = JSON.parse(stored) as Plan;
    if (Array.isArray(parsed.lanes) && Array.isArray(parsed.stations)) return parsed;
  } catch (error) {
    console.error('Could not load saved bus plan:', error);
  }
  return emptyPlan;
}

function loadFlowDirection(): FlowDirection {
  const sharedDirection = new URLSearchParams(window.location.hash.slice(1)).get('flow');
  if (sharedDirection === 'up' || sharedDirection === 'down') return sharedDirection;
  return localStorage.getItem(FLOW_DIRECTION_STORAGE_KEY) === 'down' ? 'down' : 'up';
}

function decodePlan(encoded: string): string | null {
  try {
    const binary = atob(encoded.replace(/-/g, '+').replace(/_/g, '/'));
    return new TextDecoder().decode(Uint8Array.from(binary, character => character.charCodeAt(0)));
  } catch (error) {
    console.error('Could not decode shared bus plan:', error);
    return null;
  }
}

function encodePlan(plan: Plan): string {
  const bytes = new TextEncoder().encode(JSON.stringify(plan));
  const binary = String.fromCharCode(...bytes);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function materialName(id: string): string {
  return materialById.get(id)?.name ?? id;
}

// The "standard" recipe for a material is its normal (non-alternate) recipe,
// used only to auto-check the bus inputs a freshly-dropped station is likely
// to want -- the user can freely tick/untick lanes afterward.
function standardRecipe(materialId: string) {
  const recipes = recipesForMaterial(materialId);
  return recipes.find(recipe => !recipe.alternate) ?? recipes[0];
}

function pullsLaneFromBus(station: Station, laneId: string): boolean {
  return station.busInputs?.includes(laneId) ?? false;
}

interface LaneSpan {
  first: number;
  last: number;
}

function laneTapSpan(plan: Plan, lane: Lane, flowDirection: FlowDirection): LaneSpan | null {
  let first: number | null = null;
  let last: number | null = null;
  const origin = laneOrigin(plan, lane.material, flowDirection);
  const flowStep = flowDirection === 'up' ? -1 : 1;
  const originOnlyCounterflows = laneOnlyCounterflowsFromOrigin(plan, lane, origin, flowDirection);
  plan.stations.forEach((station, index) => {
    const endpointPositions: number[] = [];
    if (station.material === lane.material) {
      endpointPositions.push(index + (originOnlyCounterflows && index === origin ? -flowStep : flowStep) * .25);
    }
    if (pullsLaneFromBus(station, lane.id)) {
      const counterflow = origin !== null && (flowDirection === 'up' ? index > origin : index < origin);
      endpointPositions.push(index + (counterflow ? flowStep : -flowStep) * .25);
    }
    for (const endpoint of endpointPositions) {
      first = first === null ? endpoint : Math.min(first, endpoint);
      last = last === null ? endpoint : Math.max(last, endpoint);
    }
  });
  if (first === null || last === null) return null;
  // Lanes without a producing station visibly enter from the flow's starting
  // edge, so they overlap every other no-origin lane at that boundary.
  return origin === null
    ? flowDirection === 'up' ? { first, last: plan.stations.length + .5 } : { first: -.5, last }
    : { first, last };
}

function spansOverlap(first: LaneSpan | null, second: LaneSpan | null): boolean {
  if (!first || !second) return false;
  return first.first <= second.last && second.first <= first.last;
}

function soleLaneSide(plan: Plan, lane: Lane): Station['side'] | null {
  let side: Station['side'] | null = null;
  for (const station of plan.stations) {
    if (station.material !== lane.material && !pullsLaneFromBus(station, lane.id)) continue;
    if (side && side !== station.side) return null;
    side = station.side;
  }
  return side;
}

function collapseLaneGroups(plan: Plan, flowDirection: FlowDirection): Lane[][] {
  const columns = plan.lanes.map(lane => [lane]);
  let moved = true;

  while (moved) {
    moved = false;
    const candidates = columns
      .flatMap((column, columnIndex) => column.map(lane => ({ lane, columnIndex, side: soleLaneSide(plan, lane) })))
      .filter((candidate): candidate is { lane: Lane; columnIndex: number; side: Station['side'] } => candidate.side !== null)
      .sort((first, second) => first.side === second.side
        ? first.side === 'left' ? first.columnIndex - second.columnIndex : second.columnIndex - first.columnIndex
        : first.side === 'left' ? -1 : 1);

    for (const { lane, columnIndex, side } of candidates) {
      const sourceColumn = columns[columnIndex];
      if (!sourceColumn?.includes(lane)) continue;
      const targetIndexes = side === 'left'
        ? Array.from({ length: columnIndex }, (_, index) => index)
        : Array.from({ length: columns.length - columnIndex - 1 }, (_, index) => columns.length - index - 1);
      const targetIndex = targetIndexes.find(index => columns[index]?.every(targetLane => !spansOverlap(
        laneTapSpan(plan, lane, flowDirection),
        laneTapSpan(plan, targetLane, flowDirection),
      )));
      if (targetIndex === undefined) continue;

      const targetColumn = columns[targetIndex]!;
      sourceColumn.splice(sourceColumn.indexOf(lane), 1);
      targetColumn.push(lane);
      if (sourceColumn.length === 0) columns.splice(columnIndex, 1);
      moved = true;
      break;
    }
  }

  return columns;
}

function MaterialIcon({ material, size = 'medium' }: { material: Material | undefined; size?: 'small' | 'medium' }) {
  if (!material) return <span class={`material-icon missing ${size}`}>?</span>;
  return <img class={`material-icon ${size}`} src={material.icon} alt="" draggable={false} />;
}

function Footer() {
  return (
    <>
      <footer class="app-footer">
        <span>A vibe-coded micro-app via <a href="https://searyanc.dev" target="_blank" rel="noopener noreferrer">SeaRyanC</a></span>
        <a class="github-link" href="https://github.com/SeaRyanC/app/tree/main/bus" target="_blank" rel="noopener noreferrer" title="View source on GitHub" aria-label="View source on GitHub">⌘</a>
        <span class="version">v{VERSION}+{COMMIT_HASH}</span>
      </footer>
      <span class="build-stamp">BUILD v{VERSION}+{COMMIT_HASH}</span>
    </>
  );
}

function ItemCard({ material, onDragStart, disabled }: { material: Material; onDragStart: (payload: DragPayload) => void; disabled: boolean }) {
  return (
    <button
      class="item-card"
      draggable={!disabled}
      disabled={disabled}
      onDragStart={event => {
        if (disabled) return;
        const payload: DragPayload = { kind: 'material', id: material.id };
        onDragStart(payload);
        event.dataTransfer?.setData('application/x-factorio-bus', JSON.stringify(payload));
        event.dataTransfer?.setData('text/plain', material.id);
        if (event.dataTransfer) event.dataTransfer.effectAllowed = 'copy';
      }}
      title={`Drag ${material.name} into the bus`}
    >
      <MaterialIcon material={material} />
      <span>{material.name}</span>
      {material.spaceAge && <em>SA</em>}
    </button>
  );
}

export const App: FunctionComponent = () => {
  const [plan, setPlan] = useState<Plan>(loadPlan);
  const [history, setHistory] = useState<Plan[]>([]);
  const [future, setFuture] = useState<Plan[]>([]);
  const [search, setSearch] = useState('');
  const [selectedStationId, setSelectedStationId] = useState<string | null>(null);
  const [highlightedStationId, setHighlightedStationId] = useState<string | null>(null);
  const [highlightedLaneId, setHighlightedLaneId] = useState<string | null>(null);
  const [collapseView, setCollapseView] = useState(false);
  const [flowDirection, setFlowDirection] = useState<FlowDirection>(loadFlowDirection);
  const [notice, setNotice] = useState('');
  const stageRef = useRef<HTMLDivElement>(null);
  const stationPortRefs = useRef(new Map<string, HTMLSpanElement>());
  const laneSpineRefs = useRef(new Map<string, HTMLSpanElement>());

  const registerStationPort = useCallback((stationId: string, element: HTMLSpanElement | null) => {
    if (element) stationPortRefs.current.set(stationId, element);
    else stationPortRefs.current.delete(stationId);
  }, []);

  const registerLaneSpine = useCallback((laneId: string, element: HTMLSpanElement | null) => {
    if (element) laneSpineRefs.current.set(laneId, element);
    else laneSpineRefs.current.delete(laneId);
  }, []);
  const setHoveredStation = useCallback((stationId: string | null) => {
    setHighlightedStationId(stationId);
    setHighlightedLaneId(null);
  }, []);
  const setHoveredLane = useCallback((laneId: string | null) => {
    setHighlightedLaneId(laneId);
    setHighlightedStationId(null);
  }, []);

  const filteredMaterials = useMemo(() => {
    const needle = search.trim().toLowerCase();
    return materials.filter(material => !needle || material.name.toLowerCase().includes(needle) || material.id.includes(needle));
  }, [search]);
  const laneGroups = useMemo(() => collapseLaneGroups(plan, flowDirection), [flowDirection, plan]);
  const visibleLaneGroups = collapseView ? laneGroups : plan.lanes.map(lane => [lane]);
  const inSituLaneIds = useMemo(
    () => new Set(collapseView ? laneGroups.filter(group => group.length > 1).flatMap(group => group.map(lane => lane.id)) : []),
    [collapseView, laneGroups],
  );

  const selectedStation = plan.stations.find(station => station.id === selectedStationId);
  const selectedStationRecipe = selectedStation ? standardRecipe(selectedStation.material) : undefined;

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(plan));
  }, [plan]);

  useEffect(() => {
    localStorage.setItem(FLOW_DIRECTION_STORAGE_KEY, flowDirection);
  }, [flowDirection]);

  const updatePlan = useCallback((next: Plan) => {
    if (collapseView) return;
    setHistory(previous => [...previous.slice(-(MAX_HISTORY - 1)), plan]);
    setFuture([]);
    setPlan(next);
  }, [collapseView, plan]);

  const addLane = useCallback((materialId: string) => {
    updatePlan({ ...plan, lanes: [...plan.lanes, { id: newId('lane'), material: materialId }] });
  }, [plan, updatePlan]);

  const addStation = useCallback((materialId: string, side: Station['side']) => {
    const recipe = standardRecipe(materialId);
    const busInputs = recipe
      ? plan.lanes.filter(lane => recipe.inputs.some(input => input.material === lane.material)).map(lane => lane.id)
      : [];
    const station: Station = { id: newId('station'), material: materialId, side, ...(busInputs.length > 0 ? { busInputs } : {}) };
    updatePlan({ ...plan, stations: [...plan.stations, station] });
    setSelectedStationId(station.id);
  }, [plan, updatePlan]);

  const toggleStationSide = useCallback((stationId: string) => {
    updatePlan({
      ...plan,
      stations: plan.stations.map(station => station.id === stationId ? { ...station, side: station.side === 'left' ? 'right' : 'left' } : station),
    });
  }, [plan, updatePlan]);

  const onDragStart = useCallback((payload: DragPayload) => {
    window.__busPlannerDrag = payload;
  }, []);

  const dropPayload = useCallback((event: DragEvent): DragPayload | null => {
    if (window.__busPlannerDrag) return window.__busPlannerDrag;
    const encoded = event.dataTransfer?.getData('application/x-factorio-bus');
    if (!encoded) return null;
    try {
      return JSON.parse(encoded) as DragPayload;
    } catch (error) {
      console.error('Could not read dragged bus payload:', error);
      return null;
    }
  }, []);

  const reorderLane = useCallback((draggedId: string, targetId: string) => {
    if (draggedId === targetId) return;
    const lanes = [...plan.lanes];
    const from = lanes.findIndex(lane => lane.id === draggedId);
    const to = lanes.findIndex(lane => lane.id === targetId);
    if (from < 0 || to < 0) return;
    const [lane] = lanes.splice(from, 1);
    if (lane) lanes.splice(to, 0, lane);
    updatePlan({ ...plan, lanes });
  }, [plan, updatePlan]);

  const reorderStation = useCallback((draggedId: string, targetId: string) => {
    if (draggedId === targetId) return;
    const stations = [...plan.stations];
    const from = stations.findIndex(station => station.id === draggedId);
    const to = stations.findIndex(station => station.id === targetId);
    if (from < 0 || to < 0) return;
    const [station] = stations.splice(from, 1);
    if (station) stations.splice(to, 0, station);
    updatePlan({ ...plan, stations });
  }, [plan, updatePlan]);

  const removeLane = useCallback((laneId: string) => {
    updatePlan({
      lanes: plan.lanes.filter(lane => lane.id !== laneId),
      stations: plan.stations.map(station => {
        const busInputs = station.busInputs?.filter(inputLaneId => inputLaneId !== laneId) ?? [];
        if (busInputs.length > 0) return { ...station, busInputs };
        const nextStation = { ...station };
        delete nextStation.busInputs;
        return nextStation;
      }),
    });
  }, [plan, updatePlan]);

  const moveStation = useCallback((stationId: string, direction: -1 | 1) => {
    const stations = [...plan.stations];
    const from = stations.findIndex(station => station.id === stationId);
    const to = from + direction;
    if (from < 0 || to < 0 || to >= stations.length) return;
    const [station] = stations.splice(from, 1);
    if (station) stations.splice(to, 0, station);
    updatePlan({ ...plan, stations });
  }, [plan, updatePlan]);

  const handleDrop = useCallback((target: 'lane' | 'station-add' | string, event: DragEvent) => {
    event.preventDefault();
    if (collapseView) return;
    const payload = dropPayload(event);
    if (!payload) return;
    const isLaneTarget = target === 'lane' || plan.lanes.some(lane => lane.id === target);
    if (isLaneTarget) {
      if (payload.kind === 'material') addLane(payload.id);
      else if (payload.kind === 'lane' && target !== 'lane') reorderLane(payload.id, target);
    } else if (target === 'station-add') {
      if (payload.kind === 'material') addStation(payload.id, 'left');
    } else if (payload.kind === 'lane') {
      reorderLane(payload.id, target);
    } else if (payload.kind === 'station') {
      reorderStation(payload.id, target);
    }
    window.__busPlannerDrag = undefined;
  }, [addLane, addStation, collapseView, dropPayload, plan.lanes, reorderLane, reorderStation]);

  const setLaneSource = useCallback((laneId: string, useBus: boolean) => {
    if (!selectedStationId) return;
    updatePlan({
      ...plan,
      stations: plan.stations.map(station => {
        if (station.id !== selectedStationId) return station;
        const busInputs = new Set(station.busInputs ?? []);
        if (useBus) busInputs.add(laneId);
        else busInputs.delete(laneId);
        if (busInputs.size > 0) return { ...station, busInputs: [...busInputs] };
        const nextStation = { ...station };
        delete nextStation.busInputs;
        return nextStation;
      }),
    });
  }, [plan, selectedStationId, updatePlan]);

  const removeSelectedStation = useCallback(() => {
    if (!selectedStationId) return;
    updatePlan({ ...plan, stations: plan.stations.filter(station => station.id !== selectedStationId) });
    setSelectedStationId(null);
  }, [plan, selectedStationId, updatePlan]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (!selectedStationId || target?.matches('input, select, textarea')) return;
      if (event.key !== 'Delete' && event.key !== 'Backspace') return;
      event.preventDefault();
      removeSelectedStation();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [removeSelectedStation, selectedStationId]);

  const undo = useCallback(() => {
    if (collapseView) return;
    const previous = history.at(-1);
    if (!previous) return;
    setFuture(current => [...current, plan]);
    setPlan(previous);
    setHistory(current => current.slice(0, -1));
  }, [collapseView, history, plan]);

  const redo = useCallback(() => {
    if (collapseView) return;
    const next = future.at(-1);
    if (!next) return;
    setHistory(current => [...current, plan]);
    setPlan(next);
    setFuture(current => current.slice(0, -1));
  }, [collapseView, future, plan]);

  const share = useCallback(async () => {
    const url = `${window.location.origin}${window.location.pathname}#plan=${encodePlan(plan)}&flow=${flowDirection}`;
    window.history.replaceState(null, '', url);
    try {
      await navigator.clipboard.writeText(url);
      setNotice('Share link copied');
    } catch {
      setNotice('Share link ready in the address bar');
    }
    window.setTimeout(() => setNotice(''), 2200);
  }, [flowDirection, plan]);

  const reset = useCallback(() => {
    if (plan.lanes.length === 0 && plan.stations.length === 0) return;
    updatePlan(emptyPlan);
    setSelectedStationId(null);
  }, [plan, updatePlan]);

  const toggleCollapseView = useCallback((enabled: boolean) => {
    setCollapseView(enabled);
    if (enabled) setSelectedStationId(null);
  }, []);

  const toggleFlowDirection = useCallback((direction: FlowDirection) => {
    setFlowDirection(direction);
    const hash = new URLSearchParams(window.location.hash.slice(1));
    hash.set('flow', direction);
    window.history.replaceState(null, '', `${window.location.pathname}${window.location.search}#${hash.toString()}`);
  }, []);

  return (
    <div class="app">
      <main class="workspace">
        <aside class="catalog panel">
          <div class="toolbar">
            <button onClick={undo} disabled={collapseView || !history.length} title="Undo (⌘Z)">↶ Undo</button>
            <button onClick={redo} disabled={collapseView || !future.length} title="Redo (⇧⌘Z)">↷ Redo</button>
            <button onClick={() => void share()} class="share-button">↗ Share link</button>
            <button onClick={reset} disabled={collapseView} class="quiet-button">Reset</button>
          </div>
          <div class="panel-heading">
            <span class="section-kicker">01 / CATALOG</span>
            <span class="count">{filteredMaterials.length}</span>
          </div>
          <label class="search-box">
            <span>⌕</span>
            <input value={search} onInput={event => setSearch((event.currentTarget as HTMLInputElement).value)} placeholder="Search items and fluids" />
          </label>
          <p class="catalog-help">Drag a material into the bus, or drop it below the stations to add one.</p>
          <div class="item-list">
            {filteredMaterials.map(material => <ItemCard key={material.id} material={material} onDragStart={onDragStart} disabled={collapseView} />)}
          </div>
        </aside>

        <section class="planner panel">
          <div class="planner-heading">
            <span class="section-kicker">02 / FIELD</span>
            <div class="planner-options">
              <label class="collapse-toggle" title="Place adjacent lanes in one column when their visible segments do not overlap">
                <input type="checkbox" checked={collapseView} onChange={event => toggleCollapseView((event.currentTarget as HTMLInputElement).checked)} />
                Collapse view
              </label>
              <label class="flow-toggle" title="Toggle which edge feeds the bus">
                <input type="checkbox" checked={flowDirection === 'down'} onChange={event => toggleFlowDirection((event.currentTarget as HTMLInputElement).checked ? 'down' : 'up')} />
                {flowDirection === 'up' ? 'bottom → top' : 'top → bottom'} <span class="arrow">{flowDirection === 'up' ? '↑' : '↓'}</span>
              </label>
            </div>
          </div>
          <div class="bus-shell">
            <div class={`bus-columns ${collapseView ? 'collapsed' : ''}`} ref={stageRef}>
            <div class="station-bay left-bay">
              <div class="bay-label">◂ stations</div>
              {plan.stations.map((station, index) => station.side === 'left' ? (
                <StationCard key={station.id} station={station} index={index} isFirst={index === 0} isLast={index === plan.stations.length - 1} selected={selectedStationId === station.id} onSelect={setSelectedStationId} onHover={setHoveredStation} onDragStart={onDragStart} onDrop={handleDrop} onToggleSide={toggleStationSide} onMove={moveStation} portRef={element => registerStationPort(station.id, element)} editingDisabled={collapseView} />
              ) : <div key={station.id} class="station-spacer" />)}
            </div>
            <div
              class="lanes"
              onDragOver={event => event.preventDefault()}
              onDrop={event => handleDrop('lane', event)}
            >
              {plan.lanes.length === 0 ? (
                <div class="empty-field"><div class="empty-icon">＋</div><strong>Drop items here to create lanes</strong><span>Your bus grows {flowDirection === 'up' ? 'upward from each item’s lowest' : 'downward from each item’s highest'} producing station.</span></div>
              ) : (
                visibleLaneGroups.map(group => group.length === 1 ? (
                  <LaneColumn key={group[0]!.id} lane={group[0]!} onDragStart={onDragStart} onDrop={handleDrop} onRemove={removeLane} onHover={setHoveredLane} spineRef={element => registerLaneSpine(group[0]!.id, element)} editingDisabled={collapseView} />
                ) : (
                  <div class="lane-column-group" key={group.map(lane => lane.id).join(':')}>
                    {group.map((lane, index) => (
                      <LaneColumn key={lane.id} lane={lane} onDragStart={onDragStart} onDrop={handleDrop} onRemove={removeLane} onHover={setHoveredLane} spineRef={element => registerLaneSpine(lane.id, element)} editingDisabled collapsedIndex={index} />
                    ))}
                  </div>
                ))
              )}
            </div>
            <div class="station-bay right-bay">
              <div class="bay-label">stations ▸</div>
              {plan.stations.map((station, index) => station.side === 'right' ? (
                <StationCard key={station.id} station={station} index={index} isFirst={index === 0} isLast={index === plan.stations.length - 1} selected={selectedStationId === station.id} onSelect={setSelectedStationId} onHover={setHoveredStation} onDragStart={onDragStart} onDrop={handleDrop} onToggleSide={toggleStationSide} onMove={moveStation} portRef={element => registerStationPort(station.id, element)} editingDisabled={collapseView} />
              ) : <div key={station.id} class="station-spacer" />)}
            </div>
            <BeltOverlay plan={plan} stageRef={stageRef} stationPortRefs={stationPortRefs} laneSpineRefs={laneSpineRefs} collapseView={collapseView} flowDirection={flowDirection} inSituLaneIds={inSituLaneIds} highlightedStationId={highlightedStationId} highlightedLaneId={highlightedLaneId} onHoverLane={setHoveredLane} />
            </div>
            <div
              class="add-station-row"
              onDragOver={event => event.preventDefault()}
              onDrop={event => handleDrop('station-add', event)}
            >
              {collapseView ? 'Collapse view is read-only · uncheck it to edit the plan' : 'Drop an item here to add a station · use ⇄ on a station to flip which side it taps from'}
            </div>
          </div>
          {plan.lanes.length > 0 && <div class="legend"><span class="legend-line" /> normal flow <span class="legend-line dashed" /> counterflow <span class="legend-note">{collapseView ? 'Read-only collapsed layout' : 'Select a station to edit its bus inputs'}</span></div>}
        </section>
      </main>

      {selectedStation && (
        <div class="modal-backdrop" onClick={event => { if (event.target === event.currentTarget) setSelectedStationId(null); }}>
          <section class="recipe-modal" role="dialog" aria-modal="true" aria-labelledby="recipe-title">
            <button class="modal-close" onClick={() => setSelectedStationId(null)} aria-label="Close">×</button>
            <div class="modal-material"><MaterialIcon material={materialById.get(selectedStation.material)} /></div>
            <span class="section-kicker">STATION / {selectedStation.side.toUpperCase()}</span>
            <h2 id="recipe-title">{materialName(selectedStation.material)}</h2>
            {selectedStationRecipe && selectedStationRecipe.inputs.length > 0 && (
              <div class="recipe-info">
                <h3>Recipe inputs</h3>
                <div class="recipe-inputs">
                  {selectedStationRecipe.inputs.map(input => (
                    <span class="recipe-input" key={input.material} title={`${input.amount} ${materialName(input.material)}`}>
                      <MaterialIcon material={materialById.get(input.material)} size="small" />
                      <span>{materialName(input.material)}</span>
                    </span>
                  ))}
                </div>
              </div>
            )}
            <div class="lane-inputs">
              <h3>Bus inputs</h3>
              {plan.lanes.length > 0 ? (
                <div class="lane-input-grid">
                  {plan.lanes.map(lane => {
                    const name = materialName(lane.material);
                    return (
                      <label class="lane-input-cell" key={lane.id} title={`${name}: ${pullsLaneFromBus(selectedStation, lane.id) ? 'pulling from bus' : 'not pulled'}`}>
                        <input
                          type="checkbox"
                          checked={pullsLaneFromBus(selectedStation, lane.id)}
                          onChange={event => setLaneSource(lane.id, (event.currentTarget as HTMLInputElement).checked)}
                          aria-label={`Pull ${name} from this lane`}
                        />
                        <MaterialIcon material={materialById.get(lane.material)} />
                        <span class="lane-input-name">{name}</span>
                      </label>
                    );
                  })}
                </div>
              ) : <p class="modal-help">Add lanes to the bus, then choose which ones this station consumes.</p>}
            </div>
            <button class="remove-button" onClick={removeSelectedStation}>Dismantle station</button>
          </section>
        </div>
      )}
      {notice && <div class="notice">{notice}</div>}
      <Footer />
    </div>
  );
};

type ConnectorKind = 'input' | 'output';

interface LogicalConnector {
  id: string;
  stationId: string;
  laneId: string;
  kind: ConnectorKind;
  counterflow: boolean;
}

interface Point {
  x: number;
  y: number;
}

// A lane spine spans the whole height of the lane track; we only need its x
// position plus the pixel y of its top and bottom edges.
interface LaneMetrics {
  x: number;
  top: number;
  bottom: number;
}

interface MeasuredLayout {
  width: number;
  height: number;
  stationPorts: Map<string, Point>;
  laneSpines: Map<string, LaneMetrics>;
}

interface BeltOverlayProps {
  plan: Plan;
  stageRef: { current: HTMLDivElement | null };
  stationPortRefs: { current: Map<string, HTMLSpanElement> };
  laneSpineRefs: { current: Map<string, HTMLSpanElement> };
  collapseView: boolean;
  flowDirection: FlowDirection;
  inSituLaneIds: ReadonlySet<string>;
  highlightedStationId: string | null;
  highlightedLaneId: string | null;
  onHoverLane: (laneId: string | null) => void;
}

// One fixed elbow radius everywhere -- never variable, never zero. Every
// connector turns from a horizontal run into the vertical lane with the exact
// same quarter-circle curve, bending in the selected lane-flow direction.
const QUARTER_TURN_CONTROL = 0.5522848;
const ELBOW_RADIUS = 12;
// Multiple connectors from one station are stacked into distinct rows around
// the station's own center row, closest-lane-first, so their horizontal runs
// don't needlessly cross one another.
const TAP_SPACING = 11;
// Radius of the little "hop" bump drawn where a connector's horizontal run
// crosses over a lane spine it isn't actually connecting to.
const HOP_RADIUS = 6;
const COLLAPSED_LANE_ICON_SIZE = 18;
const CHEVRON_HALF_WIDTH = 3.5;
const CHEVRON_HALF_HEIGHT = 4;
const CHEVRON_EDGE_PADDING = 4;
const CHEVRON_GAP = 0.08;

function chevronPath(fixedPosition: number, startPosition: number, endPosition: number, direction: -1 | 1, orientation: 'horizontal' | 'vertical'): string {
  const lowPosition = Math.min(startPosition, endPosition);
  const highPosition = Math.max(startPosition, endPosition);
  const segmentLength = highPosition - lowPosition;
  if (segmentLength <= 0) return '';

  const edgePadding = Math.min(CHEVRON_EDGE_PADDING, segmentLength / 4);
  const halfHeight = Math.min(CHEVRON_HALF_HEIGHT, (segmentLength - 2 * edgePadding) / 2);
  if (halfHeight <= 0) return '';
  const halfWidth = CHEVRON_HALF_WIDTH * halfHeight / CHEVRON_HALF_HEIGHT;
  const firstCenter = lowPosition + edgePadding + halfHeight;
  const lastCenter = highPosition - edgePadding - halfHeight;
  const spacing = halfHeight * 2 * (1 + CHEVRON_GAP);
  const count = Math.floor((lastCenter - firstCenter) / spacing) + 1;
  const remainder = lastCenter - firstCenter - (count - 1) * spacing;
  const centeredFirst = firstCenter + remainder / 2;
  return Array.from({ length: count }, (_, index) => {
    const centerY = centeredFirst + index * spacing;
    const tipPosition = centerY + direction * halfHeight;
    const shoulderPosition = centerY - direction * halfHeight;
    if (orientation === 'vertical') {
      return `M ${fixedPosition - halfWidth} ${shoulderPosition} L ${fixedPosition} ${tipPosition} L ${fixedPosition + halfWidth} ${shoulderPosition}`;
    }
    return `M ${shoulderPosition} ${fixedPosition - halfWidth} L ${tipPosition} ${fixedPosition} L ${shoulderPosition} ${fixedPosition + halfWidth}`;
  }).join(' ');
}

function stationProducesMaterial(station: Station, materialId: string): boolean {
  return station.material === materialId;
}

// Stations render top-to-bottom in DOM order (index 0 at the top). The origin
// is the producer closest to the selected flow's starting edge.
function laneOrigin(plan: Plan, materialId: string, flowDirection: FlowDirection): number | null {
  let originIndex: number | null = null;
  plan.stations.forEach((station, index) => {
    if (
      stationProducesMaterial(station, materialId)
      && (originIndex === null || (flowDirection === 'up' ? index > originIndex : index < originIndex))
    ) {
      originIndex = index;
    }
  });
  return originIndex;
}

function laneOnlyCounterflowsFromOrigin(plan: Plan, lane: Lane, origin: number | null, flowDirection: FlowDirection): boolean {
  if (origin === null) return false;
  let hasCounterflowPull = false;
  for (const [stationIndex, station] of plan.stations.entries()) {
    const counterflowSide = flowDirection === 'up' ? stationIndex > origin : stationIndex < origin;
    const regularSide = flowDirection === 'up' ? stationIndex < origin : stationIndex > origin;
    if (regularSide && (stationProducesMaterial(station, lane.material) || pullsLaneFromBus(station, lane.id))) {
      return false;
    }
    if (counterflowSide && pullsLaneFromBus(station, lane.id)) hasCounterflowPull = true;
  }
  return hasCounterflowPull;
}

function buildLogicalConnectors(plan: Plan, flowDirection: FlowDirection): LogicalConnector[] {
  const plannedLaneIds = new Set(plan.lanes.map(lane => lane.id));
  const laneOrigins = new Map(plan.lanes.map(lane => [lane.id, laneOrigin(plan, lane.material, flowDirection)]));
  const counterflowOnlyLaneIds = new Set(
    plan.lanes
      .filter(lane => laneOnlyCounterflowsFromOrigin(plan, lane, laneOrigins.get(lane.id) ?? null, flowDirection))
      .map(lane => lane.id),
  );
  const connectors = plan.stations.flatMap((station, stationIndex) => {
    const inputLaneIds = new Set((station.busInputs ?? []).filter(laneId => plannedLaneIds.has(laneId)));
    const outputLaneIds = new Set(
      plan.lanes
        .filter(lane => lane.material === station.material)
        .map(lane => lane.id),
    );
    return plan.lanes.flatMap(lane => {
      const stationConnectors: LogicalConnector[] = [];
      if (inputLaneIds.has(lane.id)) {
        const origin = laneOrigins.get(lane.id) ?? null;
        stationConnectors.push({
          id: `${station.id}:input:${lane.id}`,
          stationId: station.id,
          laneId: lane.id,
          kind: 'input',
          counterflow: origin !== null && (flowDirection === 'up' ? stationIndex > origin : stationIndex < origin),
        });
      }
      if (outputLaneIds.has(lane.id)) {
        stationConnectors.push({
          id: `${station.id}:output:${lane.id}`,
          stationId: station.id,
          laneId: lane.id,
          kind: 'output',
          counterflow: counterflowOnlyLaneIds.has(lane.id) && stationIndex === laneOrigins.get(lane.id),
        });
      }
      return stationConnectors;
    });
  });
  return connectors;
}

// Every station connector runs horizontally at a fixed offset from the
// station's own row, then turns a single fixed-radius quarter circle to merge
// into the vertical lane. The vertical bend follows the material's measured
// physical direction along that lane; logical flow is only a fallback when
// compaction puts two endpoints on the same row.
// Any other lane spine the horizontal run passes over (without connecting to
// it) gets a small circuit-diagram-style "hop" bump so crossings never read
// as a connection. Horizontal runs are rendered separately as directional
// chevrons, leaving only the vertical and curved connector geometry here.
function logicalLaneDirection(counterflow: boolean, flowDirection: FlowDirection): -1 | 1 {
  const flowSign: -1 | 1 = flowDirection === 'up' ? -1 : 1;
  return counterflow ? flowSign === -1 ? 1 : -1 : flowSign;
}

function connectorVerticalDirection(kind: ConnectorKind, laneDirection: -1 | 1): -1 | 1 {
  return kind === 'output' ? laneDirection : laneDirection === -1 ? 1 : -1;
}

function laneDirectionForConnector(kind: ConnectorKind, verticalDirection: -1 | 1): -1 | 1 {
  return kind === 'output' ? verticalDirection : verticalDirection === -1 ? 1 : -1;
}

function isCounterflowDirection(kind: ConnectorKind, verticalDirection: -1 | 1, flowDirection: FlowDirection): boolean {
  return laneDirectionForConnector(kind, verticalDirection) !== (flowDirection === 'up' ? -1 : 1);
}

function connectorCurvePath(start: Point, rowOffset: number, laneX: number, verticalDirection: -1 | 1, hopXs: number[]): string {
  const rowY = start.y + rowOffset;
  const dx = laneX - start.x;
  const sign = dx >= 0 ? 1 : -1;
  const radius = Math.min(ELBOW_RADIUS, Math.abs(dx));
  const vDir = verticalDirection;
  const entryX = laneX - sign * radius;
  const curveEndY = rowY + vDir * radius;
  const control = QUARTER_TURN_CONTROL * radius;
  const c1x = entryX + sign * control;
  const c2y = curveEndY - vDir * control;

  let d = `M ${start.x} ${start.y}`;
  if (rowOffset !== 0) d += ` V ${rowY}`;

  const sweepFlag = sign > 0 ? 1 : 0;
  const orderedHops = [...hopXs].sort((a, b) => sign > 0 ? a - b : b - a);
  for (const hopX of orderedHops) {
    d += ` M ${hopX - sign * HOP_RADIUS} ${rowY} A ${HOP_RADIUS} ${HOP_RADIUS} 0 0 ${sweepFlag} ${hopX + sign * HOP_RADIUS} ${rowY}`;
  }
  d += ` M ${entryX} ${rowY} C ${c1x} ${rowY} ${laneX} ${c2y} ${laneX} ${curveEndY}`;
  return d;
}

function connectorChevronPath(start: Point, rowOffset: number, laneX: number, kind: ConnectorKind, hopXs: number[]): string {
  const rowY = start.y + rowOffset;
  const dx = laneX - start.x;
  const pathDirection: -1 | 1 = dx >= 0 ? 1 : -1;
  const flowDirection: -1 | 1 = kind === 'output'
    ? pathDirection
    : pathDirection === 1 ? -1 : 1;
  const radius = Math.min(ELBOW_RADIUS, Math.abs(dx));
  const entryX = laneX - pathDirection * radius;
  const orderedHops = [...hopXs].sort((a, b) => pathDirection > 0 ? a - b : b - a);
  const paths: string[] = [];
  let currentX = start.x;

  for (const hopX of orderedHops) {
    const hopStartX = hopX - pathDirection * HOP_RADIUS;
    paths.push(chevronPath(rowY, currentX, hopStartX, flowDirection, 'horizontal'));
    currentX = hopX + pathDirection * HOP_RADIUS;
  }
  paths.push(chevronPath(rowY, currentX, entryX, flowDirection, 'horizontal'));
  return paths.filter(Boolean).join(' ');
}

interface LaneRangeResult {
  laneRanges: Map<string, LaneMetrics>;
  laneNormalSegments: Map<string, LaneSpineSegment[]>;
  laneCounterflowSegments: Map<string, LaneSpineSegment[]>;
}

interface LaneSpineSegment {
  start: number;
  end: number;
  direction: -1 | 1;
}

function directionalSpineSegment(anchor: number, endpoints: number[], direction: -1 | 1): LaneSpineSegment[] {
  const targets = endpoints.filter(endpoint => direction === -1 ? endpoint < anchor : endpoint > anchor);
  if (targets.length === 0) return [];
  const edge = direction === -1 ? Math.min(...targets) : Math.max(...targets);
  return [{
    start: direction === -1 ? edge : anchor,
    end: direction === -1 ? anchor : edge,
    direction,
  }];
}

function connectorRowPosition(connector: LogicalConnector, layout: MeasuredLayout, tapOffsets: Map<string, number>): number | undefined {
  const stationPort = layout.stationPorts.get(connector.stationId);
  if (!stationPort) return undefined;
  return stationPort.y + (tapOffsets.get(connector.id) ?? 0);
}

function buildConnectorVerticalDirections(
  plan: Plan,
  layout: MeasuredLayout,
  connectors: LogicalConnector[],
  tapOffsets: Map<string, number>,
  flowDirection: FlowDirection,
): Map<string, Array<-1 | 1>> {
  const verticalDirections = new Map<string, Array<-1 | 1>>();
  for (const lane of plan.lanes) {
    const metrics = layout.laneSpines.get(lane.id);
    if (!metrics) continue;
    const laneConnectors = connectors.filter(connector => connector.laneId === lane.id);
    const originIndex = laneOrigin(plan, lane.material, flowDirection);
    const originStation = originIndex === null ? undefined : plan.stations[originIndex];
    const originConnector = originStation
      ? laneConnectors.find(connector => connector.id === `${originStation.id}:output:${lane.id}`)
      : undefined;
    const boundaryRow = flowDirection === 'up' ? metrics.bottom : metrics.top;
    const originRow = originConnector
      ? connectorRowPosition(originConnector, layout, tapOffsets)
      : boundaryRow;
    if (originRow === undefined) continue;

    const originLogicalDirection = originConnector
      ? logicalLaneDirection(originConnector.counterflow, flowDirection)
      : logicalLaneDirection(false, flowDirection);
    const targetRows = laneConnectors
      .filter(connector => connector.kind === 'input' && connector.stationId !== originConnector?.stationId)
      .map(connector => connectorRowPosition(connector, layout, tapOffsets))
      .filter((row): row is number => row !== undefined && row !== originRow);
    const originPhysicalDirection = targetRows.some(row => Math.sign(row - originRow) === originLogicalDirection)
      ? originLogicalDirection
      : targetRows.length > 0
        ? (Math.sign(targetRows[0]! - originRow) as -1 | 1)
        : originLogicalDirection;

    for (const connector of laneConnectors) {
      const row = connectorRowPosition(connector, layout, tapOffsets);
      if (row === undefined) continue;
      const logicalDirection = logicalLaneDirection(connector.counterflow, flowDirection);
      const laneDirection = connector.id === originConnector?.id
        ? originPhysicalDirection
        : row === originRow
          ? logicalDirection
          : Math.sign(row - originRow) as -1 | 1;
      const directions = [connectorVerticalDirection(connector.kind, laneDirection)];
      if (connector.id === originConnector?.id) {
        const oppositeDirection = laneDirection === -1 ? 1 : -1;
        if (targetRows.some(targetRow => Math.sign(targetRow - row) === oppositeDirection)) {
          directions.push(connectorVerticalDirection(connector.kind, oppositeDirection));
        }
      }
      verticalDirections.set(connector.id, directions);
    }
  }
  return verticalDirections;
}

function connectorRowRank(connector: LogicalConnector, flowDirection: FlowDirection): number {
  const rank = connector.kind === 'output' ? connector.counterflow ? 3 : 0 : connector.counterflow ? 1 : 2;
  return flowDirection === 'up' ? rank : 3 - rank;
}

function groupConnectorsByStation(connectors: LogicalConnector[]): Map<string, LogicalConnector[]> {
  const byStation = new Map<string, LogicalConnector[]>();
  for (const connector of connectors) {
    const list = byStation.get(connector.stationId) ?? [];
    list.push(connector);
    byStation.set(connector.stationId, list);
  }
  return byStation;
}

function buildTapOffsets(byStation: Map<string, LogicalConnector[]>, layout: MeasuredLayout, flowDirection: FlowDirection): Map<string, number> {
  const tapOffsets = new Map<string, number>();
  for (const [stationId, list] of byStation) {
    const stationPort = layout.stationPorts.get(stationId);
    if (!stationPort) continue;
    const ordered = [...list].sort((first, second) => {
      const rankDifference = connectorRowRank(first, flowDirection) - connectorRowRank(second, flowDirection);
      if (rankDifference !== 0) return rankDifference;
      const firstLane = layout.laneSpines.get(first.laneId);
      const secondLane = layout.laneSpines.get(second.laneId);
      return Math.abs((firstLane?.x ?? stationPort.x) - stationPort.x) - Math.abs((secondLane?.x ?? stationPort.x) - stationPort.x);
    });
    const count = ordered.length;

    ordered.forEach((connector, index) => {
      tapOffsets.set(connector.id, (index - (count - 1) / 2) * TAP_SPACING);
    });
  }
  return tapOffsets;
}

function buildLaneRanges(plan: Plan, layout: MeasuredLayout, connectors: LogicalConnector[], tapOffsets: Map<string, number>, connectorVerticalDirections: Map<string, Array<-1 | 1>>, flowDirection: FlowDirection): LaneRangeResult {
  const laneRanges = new Map<string, LaneMetrics>();
  const laneNormalSegments = new Map<string, LaneSpineSegment[]>();
  const laneCounterflowSegments = new Map<string, LaneSpineSegment[]>();
  for (const lane of plan.lanes) {
    const metrics = layout.laneSpines.get(lane.id);
    if (!metrics) continue;
    const originIndex = laneOrigin(plan, lane.material, flowDirection);
    const laneConnectors = connectors.filter(connector => connector.laneId === lane.id);
    const connectorEndpoints = laneConnectors.flatMap(connector => {
      const port = layout.stationPorts.get(connector.stationId);
      if (!port) return [];
      const offset = tapOffsets.get(connector.id) ?? 0;
      return (connectorVerticalDirections.get(connector.id) ?? []).map(verticalDirection => ({
        connector,
        endpoint: port.y + offset + verticalDirection * ELBOW_RADIUS,
        laneDirection: laneDirectionForConnector(connector.kind, verticalDirection),
      }));
    });
    if (connectorEndpoints.length === 0) continue;

    const originStation = originIndex === null ? undefined : plan.stations[originIndex];
    const originConnectorId = originStation ? `${originStation.id}:output:${lane.id}` : undefined;
    const originEndpoints = connectorEndpoints.filter(({ connector }) => connector.id === originConnectorId);
    const boundaryEndpoint = flowDirection === 'up' ? metrics.bottom : metrics.top;
    const buildSegments = (counterflow: boolean): LaneSpineSegment[] => ([-1, 1] as Array<-1 | 1>).flatMap(direction => {
      const anchor = originIndex === null
        ? boundaryEndpoint
        : originEndpoints.find(endpoint => endpoint.laneDirection === direction)?.endpoint;
      if (anchor === undefined) return [];
      const targets = connectorEndpoints
        .filter(({ connector, laneDirection }) =>
          connector.id !== originConnectorId
          && connector.counterflow === counterflow
          && laneDirection === direction,
        )
        .map(({ endpoint }) => endpoint);
      return directionalSpineSegment(anchor, targets, direction);
    });
    const normalSegments = buildSegments(false);
    const counterflowSegments = buildSegments(true);
    const allEndpoints = connectorEndpoints.map(({ endpoint }) => endpoint);
    laneRanges.set(lane.id, {
      x: metrics.x,
      top: Math.min(...allEndpoints),
      bottom: Math.max(...allEndpoints),
    });
    if (normalSegments.length > 0) laneNormalSegments.set(lane.id, normalSegments);
    if (counterflowSegments.length > 0) laneCounterflowSegments.set(lane.id, counterflowSegments);
  }
  return { laneRanges, laneNormalSegments, laneCounterflowSegments };
}

function tapCrossingCount(layout: MeasuredLayout, connectors: LogicalConnector[], tapOffsets: Map<string, number>, laneRanges: Map<string, LaneMetrics>): number {
  let crossings = 0;
  for (const connector of connectors) {
    const stationPort = layout.stationPorts.get(connector.stationId);
    const laneSpine = layout.laneSpines.get(connector.laneId);
    if (!stationPort || !laneSpine) continue;
    const rowY = stationPort.y + (tapOffsets.get(connector.id) ?? 0);
    const lo = Math.min(stationPort.x, laneSpine.x);
    const hi = Math.max(stationPort.x, laneSpine.x);
    for (const [laneId, range] of laneRanges) {
      if (laneId === connector.laneId) continue;
      if (range.x <= lo || range.x >= hi) continue;
      if (rowY < range.top || rowY > range.bottom) continue;
      crossings += 1;
    }
  }
  return crossings;
}

function optimizeInputTapRows(plan: Plan, layout: MeasuredLayout, connectors: LogicalConnector[], byStation: Map<string, LogicalConnector[]>, tapOffsets: Map<string, number>, flowDirection: FlowDirection): Map<string, number> {
  const optimizedOffsets = new Map(tapOffsets);
  for (const list of byStation.values()) {
    let ordered = [...list].sort((first, second) => (optimizedOffsets.get(first.id) ?? 0) - (optimizedOffsets.get(second.id) ?? 0));
    for (const counterflow of [true, false]) {
      const slots = ordered
        .map((connector, index) => ({ connector, index }))
        .filter(({ connector }) => connector.kind === 'input' && connector.counterflow === counterflow);
      if (slots.length < 2) continue;

      const slotOffsets = slots.map(({ connector }) => optimizedOffsets.get(connector.id) ?? 0);
      const stationPort = layout.stationPorts.get(slots[0]!.connector.stationId);
      const scoreOrder = (candidateOrder: LogicalConnector[]) => {
        const candidateOffsets = new Map(optimizedOffsets);
        candidateOrder.forEach((connector, index) => candidateOffsets.set(connector.id, slotOffsets[index]!));
        const candidateVerticalDirections = buildConnectorVerticalDirections(plan, layout, connectors, candidateOffsets, flowDirection);
        const { laneRanges } = buildLaneRanges(plan, layout, connectors, candidateOffsets, candidateVerticalDirections, flowDirection);
        const crossings = tapCrossingCount(layout, connectors, candidateOffsets, laneRanges);
        const proximity = candidateOrder.reduce((total, connector, index) => {
          const laneX = layout.laneSpines.get(connector.laneId)?.x ?? stationPort?.x ?? 0;
          const rowPriority = counterflow ? candidateOrder.length - 1 - index : index;
          return total + Math.abs(laneX - (stationPort?.x ?? 0)) * rowPriority;
        }, 0);
        return { crossings, proximity };
      };
      const isBetterScore = (candidate: ReturnType<typeof scoreOrder>, current: ReturnType<typeof scoreOrder>) =>
        candidate.crossings < current.crossings
        || (candidate.crossings === current.crossings && candidate.proximity < current.proximity);

      let bestOrder = slots.map(({ connector }) => connector);
      let bestScore = scoreOrder(bestOrder);
      if (bestOrder.length <= 7) {
        const permutation = [...bestOrder];
        const evaluatePermutations = (start: number) => {
          if (start === permutation.length) {
            const score = scoreOrder(permutation);
            if (isBetterScore(score, bestScore)) {
              bestScore = score;
              bestOrder = [...permutation];
            }
            return;
          }
          for (let index = start; index < permutation.length; index += 1) {
            [permutation[start], permutation[index]] = [permutation[index]!, permutation[start]!];
            evaluatePermutations(start + 1);
            [permutation[start], permutation[index]] = [permutation[index]!, permutation[start]!];
          }
        };
        evaluatePermutations(0);
      } else {
        let improved = true;
        while (improved) {
          improved = false;
          for (let first = 0; first < bestOrder.length && !improved; first += 1) {
            for (let second = first + 1; second < bestOrder.length; second += 1) {
              const candidate = [...bestOrder];
              [candidate[first], candidate[second]] = [candidate[second]!, candidate[first]!];
              const score = scoreOrder(candidate);
              if (isBetterScore(score, bestScore)) {
                bestOrder = candidate;
                bestScore = score;
                improved = true;
                break;
              }
            }
          }
        }
      }

      bestOrder.forEach((connector, index) => optimizedOffsets.set(connector.id, slotOffsets[index]!));
      ordered = [...list].sort((first, second) => (optimizedOffsets.get(first.id) ?? 0) - (optimizedOffsets.get(second.id) ?? 0));
    }
  }
  return optimizedOffsets;
}

function BeltOverlay({ plan, stageRef, stationPortRefs, laneSpineRefs, collapseView, flowDirection, inSituLaneIds, highlightedStationId, highlightedLaneId, onHoverLane }: BeltOverlayProps) {
  const [layout, setLayout] = useState<MeasuredLayout | null>(null);
  const connectors = useMemo(() => buildLogicalConnectors(plan, flowDirection), [flowDirection, plan]);

  useLayoutEffect(() => {
    let disposed = false;
    let frame = 0;
    const stage = stageRef.current;
    setLayout(null);
    if (!stage || plan.lanes.length === 0) return () => undefined;

    const measure = () => {
      if (disposed) return;
      const stageRect = stage.getBoundingClientRect();
      const stageLeft = stageRect.left + stage.clientLeft;
      const stageTop = stageRect.top + stage.clientTop - stage.scrollTop;
      const width = stage.clientWidth;
      const height = stage.scrollHeight;
      if (width <= 0 || height <= 0) return;

      const stationPorts = new Map<string, Point>();
      for (const station of plan.stations) {
        const anchor = stationPortRefs.current.get(station.id);
        if (!anchor) return;
        const rect = anchor.getBoundingClientRect();
        stationPorts.set(station.id, {
          x: rect.left + rect.width / 2 - stageLeft,
          y: rect.top + rect.height / 2 - stageTop,
        });
      }

      const laneSpines = new Map<string, LaneMetrics>();
      for (const lane of plan.lanes) {
        const anchor = laneSpineRefs.current.get(lane.id);
        if (!anchor) return;
        const rect = anchor.getBoundingClientRect();
        laneSpines.set(lane.id, {
          x: rect.left + rect.width / 2 - stageLeft,
          top: rect.top - stageTop,
          bottom: rect.bottom - stageTop,
        });
      }

      setLayout({ width, height, stationPorts, laneSpines });
    };

    const scheduleMeasure = () => {
      if (disposed) return;
      setLayout(null);
      if (frame) cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        frame = 0;
        measure();
      });
    };

    const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(scheduleMeasure);
    observer?.observe(stage);
    stationPortRefs.current.forEach(anchor => observer?.observe(anchor));
    laneSpineRefs.current.forEach(anchor => observer?.observe(anchor));
    scheduleMeasure();

    return () => {
      disposed = true;
      if (frame) cancelAnimationFrame(frame);
      observer?.disconnect();
    };
  }, [collapseView, flowDirection, laneSpineRefs, plan, stageRef, stationPortRefs]);

  if (!layout || plan.lanes.length === 0) return null;

  const byStation = groupConnectorsByStation(connectors);
  let tapOffsets = buildTapOffsets(byStation, layout, flowDirection);
  for (let pass = 0; pass < 2; pass += 1) {
    tapOffsets = optimizeInputTapRows(plan, layout, connectors, byStation, tapOffsets, flowDirection);
  }
  const connectorVerticalDirections = buildConnectorVerticalDirections(plan, layout, connectors, tapOffsets, flowDirection);
  const laneRangeResult = buildLaneRanges(plan, layout, connectors, tapOffsets, connectorVerticalDirections, flowDirection);
  const { laneRanges, laneNormalSegments, laneCounterflowSegments } = laneRangeResult;
  const highlightedStation = plan.stations.find(station => station.id === highlightedStationId);
  const highlightedLaneIds = new Set(highlightedStation?.busInputs ?? []);
  const highlightedMaterials = [...new Set(
    plan.lanes
      .filter(lane => highlightedLaneIds.has(lane.id))
      .map(lane => lane.material),
  )].sort();
  const highlightedMaterialColors = new Map(
    highlightedMaterials.map((material, index) => [material, `hsl(${Math.round(index * 360 / highlightedMaterials.length)} 84% 62%)`]),
  );
  const highlightedLaneColors = new Map(
    plan.lanes
      .filter(lane => highlightedLaneIds.has(lane.id))
      .map(lane => [lane.id, highlightedMaterialColors.get(lane.material)!]),
  );
  const laneHoverColor = highlightedLaneId ? 'var(--cyan)' : undefined;

  // Lane chevrons point in the direction material flows from the selected
  // origin. In collapsed view, each physical segment points toward its actual
  // destination, since independent station bays can invert logical row order.
  const laneSpineElements = plan.lanes.map(lane => {
    const range = laneRanges.get(lane.id);
    if (!range) return null;
    const normalChevrons = (laneNormalSegments.get(lane.id) ?? [])
      .map(segment => chevronPath(range.x, segment.start, segment.end, segment.direction, 'vertical'))
      .filter(Boolean)
      .join(' ');
    const counterflowChevrons = (laneCounterflowSegments.get(lane.id) ?? [])
      .map(segment => chevronPath(range.x, segment.start, segment.end, segment.direction, 'vertical'))
      .filter(Boolean)
      .join(' ');
    const isHighlightedLane = lane.id === highlightedLaneId;
    const laneHighlightStyle = isHighlightedLane ? `--highlight-color: ${laneHoverColor};` : undefined;
    return (
      <g key={lane.id}>
        {normalChevrons && <path class={`chevron lane-chevron ${isHighlightedLane ? 'highlighted' : ''}`} style={laneHighlightStyle} d={normalChevrons} />}
        {counterflowChevrons && (
          <path class={`chevron lane-chevron counterflow ${isHighlightedLane ? 'highlighted' : ''}`} style={laneHighlightStyle} d={counterflowChevrons} />
        )}
      </g>
    );
  });
  const highlightedLaneSegments = plan.lanes.map(lane => {
    const highlightColor = highlightedLaneColors.get(lane.id);
    const laneSpine = layout.laneSpines.get(lane.id);
    const targetConnector = connectors.find(connector => connector.stationId === highlightedStationId && connector.laneId === lane.id && connector.kind === 'input');
    if (!highlightColor || !laneSpine || !targetConnector) return null;

    const targetPort = layout.stationPorts.get(targetConnector.stationId);
    const targetVerticalDirection = connectorVerticalDirections.get(targetConnector.id)?.[0];
    if (!targetPort || targetVerticalDirection === undefined) return null;
    const targetY = targetPort.y + (tapOffsets.get(targetConnector.id) ?? 0) + targetVerticalDirection * ELBOW_RADIUS;
    const originIndex = laneOrigin(plan, lane.material, flowDirection);
    const originStation = originIndex === null ? undefined : plan.stations[originIndex];
    const originPort = originStation ? layout.stationPorts.get(originStation.id) : undefined;
    const originConnector = originStation ? connectors.find(connector => connector.id === `${originStation.id}:output:${lane.id}`) : undefined;
    const originVerticalDirections = originConnector ? connectorVerticalDirections.get(originConnector.id) : undefined;
    const targetLaneDirection = laneDirectionForConnector(targetConnector.kind, targetVerticalDirection);
    const originVerticalDirection = originVerticalDirections?.find(verticalDirection =>
      laneDirectionForConnector('output', verticalDirection) === targetLaneDirection,
    ) ?? originVerticalDirections?.[0];
    const originY = originPort
      && originConnector
      && originVerticalDirection !== undefined
      ? originPort.y + (tapOffsets.get(originConnector.id) ?? 0) + originVerticalDirection * ELBOW_RADIUS
      : flowDirection === 'up' ? laneSpine.bottom : laneSpine.top;

    const direction = targetY >= originY ? 1 : -1;
    const chevrons = chevronPath(laneSpine.x, originY, targetY, direction, 'vertical');
    return chevrons
      ? <path key={lane.id} class={`chevron lane-chevron highlighted ${targetConnector.counterflow ? 'counterflow' : ''}`} style={`--highlight-color: ${highlightColor};`} d={chevrons} />
      : null;
  });
  const collapsedLaneIndicators = plan.lanes.map(lane => {
    if (!inSituLaneIds.has(lane.id)) return null;
    const range = laneRanges.get(lane.id);
    const material = materialById.get(lane.material);
    if (!range || !material) return null;
    return (
      <image
        key={lane.id}
        class={`collapsed-lane-indicator ${highlightedLaneId === lane.id ? 'highlighted' : ''}`}
        href={material.icon}
        x={range.x - COLLAPSED_LANE_ICON_SIZE / 2}
        y={Math.max(0, range.top - COLLAPSED_LANE_ICON_SIZE - 4)}
        width={COLLAPSED_LANE_ICON_SIZE}
        height={COLLAPSED_LANE_ICON_SIZE}
        preserveAspectRatio="xMidYMid meet"
        onPointerEnter={() => onHoverLane(lane.id)}
        onPointerLeave={() => onHoverLane(null)}
      />
    );
  });

  return (
    <svg
      class="belt-overlay"
      aria-hidden="true"
      width={layout.width}
      height={layout.height}
      viewBox={`0 0 ${layout.width} ${layout.height}`}
    >
      {laneSpineElements}
      {highlightedLaneSegments}
      {connectors.map(connector => {
        const stationPort = layout.stationPorts.get(connector.stationId);
        const laneSpine = layout.laneSpines.get(connector.laneId);
        if (!stationPort || !laneSpine) return null;

        const rowOffset = tapOffsets.get(connector.id) ?? 0;
        const rowY = stationPort.y + rowOffset;
        const lo = Math.min(stationPort.x, laneSpine.x);
        const hi = Math.max(stationPort.x, laneSpine.x);
        const hopXs: number[] = [];
        for (const [laneId, range] of laneRanges) {
          if (laneId === connector.laneId) continue;
          if (range.x <= lo || range.x >= hi) continue;
          if (rowY < range.top || rowY > range.bottom) continue;
          hopXs.push(range.x);
        }

        const verticalDirections = connectorVerticalDirections.get(connector.id);
        if (!verticalDirections?.length) return null;
        const chevrons = connectorChevronPath(stationPort, rowOffset, laneSpine.x, connector.kind, hopXs);

        const originIndex = laneOrigin(plan, plan.lanes.find(lane => lane.id === connector.laneId)?.material ?? '', flowDirection);
        const originStation = originIndex === null ? undefined : plan.stations[originIndex];
        const isHighlightedInput = connector.stationId === highlightedStationId && connector.kind === 'input';
        const isHighlightedOrigin = connector.kind === 'output' && connector.stationId === originStation?.id;
        const isHighlightedLane = connector.laneId === highlightedLaneId;
        const highlightColor = isHighlightedLane
          ? laneHoverColor
          : isHighlightedInput || isHighlightedOrigin ? highlightedLaneColors.get(connector.laneId) : undefined;
        const highlightStyle = highlightColor ? `--highlight-color: ${highlightColor};` : undefined;
        const primaryCounterflow = isCounterflowDirection(connector.kind, verticalDirections[0]!, flowDirection);
        const chevronClasses = `chevron connector-chevron ${connector.kind} ${primaryCounterflow ? 'counterflow' : ''} ${highlightColor ? 'highlighted' : ''}`;
        return (
          <g key={connector.id}>
            {verticalDirections.map((verticalDirection, index) => {
              const counterflow = isCounterflowDirection(connector.kind, verticalDirection, flowDirection);
              const connectorClasses = `connector ${connector.kind} ${counterflow ? 'counterflow' : ''} ${highlightColor ? 'highlighted' : ''}`;
              return (
                <path
                  key={`${connector.id}:curve:${index}`}
                  class={connectorClasses}
                  style={highlightStyle}
                  d={connectorCurvePath(stationPort, rowOffset, laneSpine.x, verticalDirection, hopXs)}
                />
              );
            })}
            {chevrons && <path class={chevronClasses} style={highlightStyle} d={chevrons} />}
          </g>
        );
      })}
      {collapsedLaneIndicators}
    </svg>
  );
}


interface StationCardProps {
  station: Station;
  index: number;
  isFirst: boolean;
  isLast: boolean;
  selected: boolean;
  onSelect: (id: string) => void;
  onHover: (id: string | null) => void;
  onDragStart: (payload: DragPayload) => void;
  onDrop: (target: string, event: DragEvent) => void;
  onToggleSide: (id: string) => void;
  onMove: (id: string, direction: -1 | 1) => void;
  portRef: (element: HTMLSpanElement | null) => void;
  editingDisabled: boolean;
}

function StationCard({ station, index, isFirst, isLast, selected, onSelect, onHover, onDragStart, onDrop, onToggleSide, onMove, portRef, editingDisabled }: StationCardProps) {
  return (
    <div
      class={`station-card ${selected ? 'selected' : ''}`}
      role="button"
      tabIndex={editingDisabled ? -1 : 0}
      draggable={!editingDisabled}
      onPointerEnter={() => onHover(station.id)}
      onPointerLeave={() => onHover(null)}
      onClick={() => { if (!editingDisabled) onSelect(station.id); }}
      onKeyDown={event => { if (!editingDisabled && (event.key === 'Enter' || event.key === ' ')) onSelect(station.id); }}
      onDragStart={() => { if (!editingDisabled) onDragStart({ kind: 'station', id: station.id }); }}
      onDragOver={event => { if (!editingDisabled) event.preventDefault(); }}
      onDrop={event => {
        if (editingDisabled) return;
        event.preventDefault();
        event.stopPropagation();
        onDrop(station.id, event);
      }}
      title={`${materialName(station.material)} · station ${index + 1}${editingDisabled ? '' : ' · click to edit bus inputs'}`}
    >
      <span ref={portRef} class={`station-port-anchor ${station.side}`} aria-hidden="true" />
      <MaterialIcon material={materialById.get(station.material)} />
      {!editingDisabled && <span class="station-controls">
        <button
          class="move-button"
          disabled={isFirst}
          title="Move up (toward the top of the bus)"
          onClick={event => { event.stopPropagation(); onMove(station.id, -1); }}
        >▲</button>
        <button
          class="side-toggle"
          title={`Tapping from the ${station.side} side · click to flip`}
          onClick={event => { event.stopPropagation(); onToggleSide(station.id); }}
        >⇄</button>
        <button
          class="move-button"
          disabled={isLast}
          title="Move down (toward the bottom of the bus)"
          onClick={event => { event.stopPropagation(); onMove(station.id, 1); }}
        >▼</button>
      </span>}
    </div>
  );
}

function LaneColumn({ lane, onDragStart, onDrop, onRemove, onHover, spineRef, editingDisabled, collapsedIndex }: { lane: Lane; onDragStart: (payload: DragPayload) => void; onDrop: (target: string, event: DragEvent) => void; onRemove: (id: string) => void; onHover: (laneId: string | null) => void; spineRef: (element: HTMLSpanElement | null) => void; editingDisabled: boolean; collapsedIndex?: number }) {
  const material = materialById.get(lane.material);
  return (
    <div class={`lane-column ${collapsedIndex === undefined ? '' : 'collapsed'}`} style={collapsedIndex === undefined ? undefined : `--collapse-index: ${collapsedIndex};`} draggable={!editingDisabled} onPointerEnter={() => onHover(lane.id)} onPointerLeave={() => onHover(null)} onDragStart={() => { if (!editingDisabled) onDragStart({ kind: 'lane', id: lane.id }); }} onDragOver={event => { if (!editingDisabled) event.preventDefault(); }} onDrop={event => { if (!editingDisabled) onDrop(lane.id, event); }} title={material?.name ?? lane.material}>
      <div class="lane-header">
        <MaterialIcon material={material} />
        {!editingDisabled && <button class="lane-remove" onClick={event => { event.stopPropagation(); onRemove(lane.id); }} aria-label={`Remove ${material?.name ?? lane.material} lane`} title="Remove lane">×</button>}
      </div>
      <div class="lane-track">
        <span ref={spineRef} class="lane-spine-anchor" aria-hidden="true" />
      </div>
    </div>
  );
}

declare global {
  interface Window {
    __busPlannerDrag: DragPayload | undefined;
  }
}
